71	namespace {
72	class AbortCompletedPieceRequest {
73	private:
74	  BtMessageDispatcher* dispatcher_;
75	
76	public:
77	  AbortCompletedPieceRequest(BtMessageDispatcher* dispatcher)
78	      : dispatcher_(dispatcher)
79	  {
80	  }
81	
82	  void operator()(const std::shared_ptr<Piece>& piece)
83	  {
84	    if (piece->pieceComplete()) {
85	      dispatcher_->doAbortOutstandingRequestAction(piece);
86	    }
87	  }
88	};
