101	    const std::shared_ptr<Piece>& piece)
102	{
103	  pieces_.erase(
104	      std::remove_if(pieces_.begin(), pieces_.end(), derefEqual(piece)),
105	      pieces_.end());
106	  dispatcher_->doAbortOutstandingRequestAction(piece);
107	  pieceStorage_->cancelPiece(piece, cuid_);
