111	class ProcessChokedPiece {
112	private:
113	  std::shared_ptr<Peer> peer_;
114	  PieceStorage* pieceStorage_;
115	  cuid_t cuid_;
116	
117	public:
118	  ProcessChokedPiece(std::shared_ptr<Peer> peer, PieceStorage* pieceStorage,
119	                     cuid_t cuid)
120	      : peer_(std::move(peer)), pieceStorage_(pieceStorage), cuid_(cuid)
121	  {
122	  }
123	
124	  void operator()(const std::shared_ptr<Piece>& piece)
125	  {
126	    if (!peer_->isInPeerAllowedIndexSet(piece->getIndex())) {
127	      pieceStorage_->cancelPiece(piece, cuid_);
128	    }
129	  }
130	};
