166	std::vector<std::unique_ptr<BtRequestMessage>>
167	DefaultBtRequestFactory::createRequestMessages(size_t max, bool endGame)
168	{
169	  if (endGame) {
170	    return createRequestMessagesOnEndGame(max);
171	  }
172	  auto requests = std::vector<std::unique_ptr<BtRequestMessage>>{};
173	  size_t getnum = max - requests.size();
174	  auto blockIndexes = std::vector<size_t>{};
175	  blockIndexes.reserve(getnum);
176	  for (auto itr = std::begin(pieces_), eoi = std::end(pieces_);
177	       itr != eoi && getnum; ++itr) {
178	    auto& piece = *itr;
179	    if (piece->getMissingUnusedBlockIndex(blockIndexes, getnum)) {
180	      getnum -= blockIndexes.size();
181	      for (auto i = std::begin(blockIndexes), eoi2 = std::end(blockIndexes);
182	           i != eoi2; ++i) {
183	        A2_LOG_DEBUG(
184	            fmt("Creating RequestMessage index=%lu, begin=%u,"
185	                " blockIndex=%lu",
186	                static_cast<unsigned long>(piece->getIndex()),
187	                static_cast<unsigned int>((*i) * piece->getBlockLength()),
188	                static_cast<unsigned long>(*i)));
189	        requests.push_back(messageFactory_->createRequestMessage(piece, *i));
190	      }
191	      blockIndexes.clear();
192	    }
193	  }
194	  return requests;
195	}
196	
197	std::vector<std::unique_ptr<BtRequestMessage>>
198	DefaultBtRequestFactory::createRequestMessagesOnEndGame(size_t max)
199	{
200	  auto requests = std::vector<std::unique_ptr<BtRequestMessage>>{};
201	  for (auto itr = std::begin(pieces_), eoi = std::end(pieces_);
202	       itr != eoi && requests.size() < max; ++itr) {
203	    auto& piece = *itr;
204	    const size_t mislen = piece->getBitfieldLength();
205	    auto misbitfield = make_unique<unsigned char[]>(mislen);
206	
207	    piece->getAllMissingBlockIndexes(misbitfield.get(), mislen);
208	
209	    auto missingBlockIndexes = std::vector<size_t>{};
210	    size_t blockIndex = 0;
211	    for (size_t i = 0; i < mislen; ++i) {
212	      unsigned char bits = misbitfield[i];
213	      unsigned char mask = 128;
214	      for (size_t bi = 0; bi < 8; ++bi, mask >>= 1, ++blockIndex) {
215	        if (bits & mask) {
216	          missingBlockIndexes.push_back(blockIndex);
217	        }
218	      }
219	    }
220	    std::shuffle(std::begin(missingBlockIndexes), std::end(missingBlockIndexes),
221	                 *SimpleRandomizer::getInstance());
222	    for (auto bitr = std::begin(missingBlockIndexes),
223	              eoi2 = std::end(missingBlockIndexes);
224	         bitr != eoi2 && requests.size() < max; ++bitr) {
225	      size_t blockIndex = *bitr;
226	      if (!dispatcher_->isOutstandingRequest(piece->getIndex(), blockIndex)) {
227	        A2_LOG_DEBUG(
228	            fmt("Creating RequestMessage index=%lu, begin=%u,"
229	                " blockIndex=%lu",
230	                static_cast<unsigned long>(piece->getIndex()),
231	                static_cast<unsigned int>(blockIndex * piece->getBlockLength()),
232	                static_cast<unsigned long>(blockIndex)));
233	        requests.push_back(
234	            messageFactory_->createRequestMessage(piece, blockIndex));
235	      }
236	    }
237	  }
238	  return requests;
239	}
